"""Assess the rejected paired candidate without inferring missing native binding data."""
from probe_aircraft_a52 import *

def main():
 guard();target=OUT/'paired_binding_and_sparse_fault_review.json';assert not target.exists();c=read(CFG);ref=read(OUT/'WHOLE_ORIGINAL_TYPE2_BINDING_TRACE/type2_trace_result.json');candidate=read(OUT/'WHOLE_PAIRED_TYPE2_BINDING_TRACE_R1/type2_trace_result.json');fault=read(OUT/'WHOLE_PAIRED_SPARSE_FAULT_TRACE/trace_result.json')
 bindings=[b for call in ref['calls'] for b in call['bindings']];assert len(ref['calls'])==432 and len(bindings)==3024 and len({b['secondary_original_label'] for b in bindings})==3024
 assert candidate['Engine_exit_code']==3 and not candidate['calls'];f=fault['fault'];assert fault['Engine_exit_code']==3 and f['function_relative_fault_hex']=='0x664';bad=[r for r in f['sparse_rows'] if any(not q['column_present'] for q in r['sparse_search'])];assert len(bad)==24
 # Preserve actual fields verbatim; no substitution of the unrelated last CBAKE3 block.
 missing=sum(sum(not q['column_present'] for q in r['sparse_search']) for r in bad);patterns=sorted({tuple(r['NDOF']) for r in bad});assert missing==144 and patterns==[(6,6)]
 d=OUT/'WHOLE_PAIRED_TYPE2_BINDING_TRACE_R1';S=parse(ROOT/c['source_files']['input']['path']);p=d/'A52_TYPE2_FACET_PAIRS_R1_0000.rad';T=parse(p);allowed={k for i in range(16000,16432,2) for k in ['/GRNOD/NODE/'+str(i),'/SURF/PART/'+str(i),'/INTER/TYPE2/'+str(i+1)]}|{'/BEGIN','/TITLE'};same=[k for k,v in S.items() if k not in allowed and T.get(k)==v];assert len(same)==len(S)-len(allowed);assert p.read_text().startswith('#RADIOSS STARTER\n');assert not any(n>1 for n in Counter(line for line in (ROOT/c['source_files']['input']['path']).read_text().splitlines() if line.startswith('/')).values())
 dump(OUT/'input_preservation_review.json',{'created_utc':now(),'pass_sections_and_header':True,'source_duplicate_keywords':0,'unchanged_sections':len(same),'removed_TYPE2_definitions':216,'union_secondary_groups':216,'union_main_surfaces':216,'physical_elements_geometry_materials_properties_masses_RBE2_RBE3_TYPE25_IC_BCS_unchanged':True,'native_binding_equivalence_not_assumed':True,'initial_header_omission_retained':True})
 listing=(d/'A52_TYPE2_FACET_PAIRS_R1_0000.out').read_text();m=re.search(r'TOTAL MASS AND MASS CENTER.*?\n\s*([\d.E+\-]+)\s+([\d.E+\-]+)\s+([\d.E+\-]+)\s+([\d.E+\-]+)',listing,re.S);mass=float(m.group(1));center=[float(v) for v in m.groups()[1:]];added=float(re.search(r'TOTAL ADDED MASS\s*=\s*([\d.E+\-]+)',listing).group(1));baseline=read(ROOT/'wtc1_simulation_v8/output/aircraft_a49/WHOLE_EQUIVALENT_RIGID_CHAINS_CHECK/mass_review.json');masspass=mass==baseline['mass_g'] and center==baseline['center_mm'] and added==baseline['prescribed_ADMAS_g'];assert masspass
 massreview={'created_utc':now(),'pass_Starter_totals':masspass,'mass_g':mass,'center_mm':center,'prescribed_ADMAS_g':added,'native_redistributed_mass_or_inertia_not_inferred':True,'no_compensation_added':True};dump(OUT/'mass_review.json',massreview)
 b=f.get('native_shell_block') or {};sameblock=b.get('same_NEL_as_assembly',False);assert not sameblock and b['scalars']['JLT']==8 and f['native_args']['NEL']==128
 result={'created_utc':now(),'original_native_TYPE2_calls':432,'original_native_secondary_bindings':3024,'original_native_binding_modes':dict(Counter(r['mode'] for r in ref['calls'])),'original_CHECK_Engine_exit':ref['Engine_exit_code'],'paired_CHECK_Engine_exit':candidate['Engine_exit_code'],'paired_native_TYPE2_calls':0,'native_binding_comparison_available':False,'native_binding_equivalence_gate_pass':False,'candidate_rejected':True,'candidate_Starter_warning_count':read(d/'starter_gate.json')['warnings'],'candidate_Starter_error_count':read(d/'starter_gate.json')['errors'],'candidate_Starter_strict_pass':False,'mass_review':massreview,'grouped_sparse_fault':{'ASSEMC_relative_offset':'0x664','assembly_calls':fault['assembly_call_count'],'last_CBAKE3_calls':fault['shell_call_count'],'native_IKPAT':f['native_IKPAT'],'assembly_NEL':f['native_args']['NEL'],'assembly_ND':f['native_args']['ND'],'missing_pairs':len(bad),'missing_rows':missing,'NDOF_patterns':[list(v) for v in patterns],'invalid_KLT_index_1based':f['destination_KLT_index_from_RAX_1based'],'last_CBAKE3_NEL':b['scalars']['JLT'],'last_CBAKE3_same_assembly_block':False,'last_CBAKE3_elements_not_assigned_to_fault':True,'actual_fault_source_element_or_original_node_labels_verified':False},'unsupported_TYPE25_count':(d/'engine.log').read_text().count('INTERFACE TYPE 25 IS NOT AVAILABLE'),'new_Starter_executions':2,'new_Engine_executions':3,'prior_failed_header_attempt_preserved':True,'software_runtime_or_process_mechanical_data_patched':False,'whole_impact_qualified':False,'new_whole_duration_credit_s':0}
 dump(target,result);print({'candidate_rejected':True,'native_binding_comparison_available':False,'missing_pairs':24,'missing_rows':144,'last_CBAKE3_block_is_not_faulting_block':True,'Starter_mass_center_ADMAS_unchanged':True},flush=True)

if __name__=='__main__':main()
